    { to: '/student/profile', label: 'Profile',        },
    { to: '/student/classes', label: 'Classes',        },
    { to: '/student/results', label: 'Check Results',  },
    { to: '/student/lms',     label: 'Tests & Quizzes' }
  ],
  teacher: [
    { to: '/teacher/home',    label: 'Dashboard',      },
    { to: '/teacher/profile', label: 'Profile',        },
    { to: '/teacher/classes', label: 'My Classes',     },
    { to: '/teacher/lms',     label: 'Tests & Quizzes' }
  ],
  admin: [
    { to: '/admin/home',      label: 'Dashboard',      },
    { to: '/admin/profile',   label: 'Profile',        },
    { to: '/admin/students',  label: 'Students',       },
    { to: '/admin/teachers',  label: 'Teachers',       },
    { to: '/admin/results',   label: 'Student Results',},
    { to: '/admin/lms',       label: 'Performance',    }
  ]
};
